mapper.select:
SELECT pp.project_id, hcpl.CREDIT_PLAN_ID, hcpl.line_id, hbm.bp_id, hbm.bp_name, hbm.bp_name bp_name_n, hbm.bp_code, hbm.bp_type, ( SELECT sc.meaning FROM sys_code_value_b_v sc WHERE sc.CODE = 'BP.BP_MASTER_ROLE' AND sc.code_value = hbm.bp_type ) bp_type_n, hbm.group_companies, hcpl.factoring_category, ( SELECT sc.meaning FROM sys_code_value_b_v sc WHERE sc.code = 'CHANCE.FACTORING_CATEGORY' AND sc.code_value = hcpl.factoring_category ) factoring_category_n, hcpl.credit_amt, hcpl.description, (select sum(hcpl2.credit_amt) from hls_credit_plan hcp2, hls_credit_plan_line hcpl2, con_contract cc where hcp2.credit_plan_id = hcpl2.credit_plan_id and hcp2.source_document_category = 'CON_CONTRACT' and hcpl2.factoring_category = hcpl.factoring_category and hcp2.credit_plan_id = hcpl.credit_plan_id and cc.project_id = pp.project_id and cc.document_type = 'FACTORING' and cc.data_class = 'NORMAL' and cc.contract_status = 'APPROVING' and cc.document_category = 'CON_CONTRACT' and cc.contract_id = hcp2.source_document_id) approval_amount, (select sum(hcpl2.credit_amt) from hls_credit_plan hcp2, hls_credit_plan_line hcpl2, con_contract cc where hcp2.credit_plan_id = hcpl2.credit_plan_id and hcp2.source_document_category = 'CON_CONTRACT' and hcpl2.factoring_category = hcpl.factoring_category and hcp2.credit_plan_id = hcpl.credit_plan_id and cc.project_id = pp.project_id and cc.document_type = 'FACTORING' and cc.data_class = 'NORMAL' and cc.contract_status = 'APPROVED' and cc.document_category = 'CON_CONTRACT' and cc.contract_id = hcp2.source_document_id) occ_amount, hcpl.credit_amt - (select sum(hcpl2.credit_amt) from hls_credit_plan hcp2, hls_credit_plan_line hcpl2, con_contract cc where hcp2.credit_plan_id = hcpl2.credit_plan_id and hcp2.source_document_category = 'CON_CONTRACT' and hcpl2.factoring_category = hcpl.factoring_category and hcp2.credit_plan_id = hcpl.credit_plan_id and cc.project_id = pp.project_id and cc.document_type = 'FACTORING' and cc.data_class = 'NORMAL' and cc.contract_status = 'APPROVED' and cc.document_category = 'CON_CONTRACT' and cc.contract_id = hcp2.source_document_id) due_amount FROM hls_credit_plan_line hcpl INNER JOIN hls_credit_plan hcp ON hcp.credit_plan_id = hcpl.credit_plan_id INNER JOIN prj_project pp ON hcp.source_document_category = 'PRJ_PROJECT' AND hcp.source_document_id = pp.project_id INNER JOIN hls_bp_master hbm ON pp.tenant_id = hbm.bp_id
hbm.bp_type = 'ASSET_TRANSFEROR'
and hcpl.credit_plan_id = #{creditPlanId}
and hcp.source_document_id = #{projectId}
